import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';

import type { LineageEdge, LineageNode, WarehouseLineageStatus } from '../../src/api/assets';
import { LineageGraph } from '../../src/components/assets/LineageGraph';

const CENTER = {
  id: 'c',
  name: 'ANALYTICS.PUBLIC.ORDERS',
  namespace: 'snowflake://acct',
  env: 'dev',
};

function node(id: string, name: string, depth: number, isMonitored = false): LineageNode {
  return {
    id,
    name,
    namespace: 'snowflake://acct',
    env: 'dev',
    is_monitored: isMonitored,
    depth,
  };
}

const UP = [node('u1', 'RAW.ORDERS', 1)];
const DOWN = [node('d1', 'ANALYTICS.MART.REVENUE', 1, true), node('d2', 'BI.DASH.SALES', 2)];
const EDGES: LineageEdge[] = [
  { source: 'u1', target: 'c' },
  { source: 'c', target: 'd1' },
  { source: 'd1', target: 'd2' },
];

function renderGraph(onOpenAsset = vi.fn()) {
  render(
    <LineageGraph
      center={CENTER}
      upstream={UP}
      downstream={DOWN}
      edges={EDGES}
      onOpenAsset={onOpenAsset}
    />,
  );
  return onOpenAsset;
}

describe('LineageGraph (#805)', () => {
  it('draws one edge per real backend edge, with direction arrows', () => {
    renderGraph();
    const graph = screen.getByRole('img', { name: /Lineage graph/ });
    expect(graph.querySelectorAll('path[marker-end]')).toHaveLength(3);
  });

  it('opens the asset a node points at when clicked', async () => {
    const onOpen = renderGraph();
    await userEvent.click(screen.getByLabelText(/Open asset ANALYTICS\.MART\.REVENUE/));
    expect(onOpen).toHaveBeenCalledWith('d1');
  });

  it('reaches a depth-2 node — the blast radius is not truncated to one hop', async () => {
    const onOpen = renderGraph();
    await userEvent.click(screen.getByLabelText('Open asset BI.DASH.SALES'));
    expect(onOpen).toHaveBeenCalledWith('d2');
  });

  it('is keyboard operable (Enter on a focused node)', async () => {
    const onOpen = renderGraph();
    const target = screen.getByLabelText('Open asset RAW.ORDERS');
    target.focus();
    await userEvent.keyboard('{Enter}');
    expect(onOpen).toHaveBeenCalledWith('u1');
  });

  it('signals "monitored" without relying on colour alone (WCAG 1.4.1)', () => {
    renderGraph();
    // d1 is monitored: it says so in its accessible name…
    expect(screen.getByLabelText('Open asset ANALYTICS.MART.REVENUE (monitored)')).toBeVisible();
    // …and an unmonitored node does not claim to be.
    expect(screen.getByLabelText('Open asset BI.DASH.SALES')).toBeVisible();
    // …plus a non-colour glyph marks it on the node itself.
    const graph = screen.getByRole('img', { name: /Lineage graph/ });
    expect(graph.querySelectorAll('circle')).toHaveLength(1);
  });

  it('labels but does not make the centre asset actionable', () => {
    renderGraph();
    expect(screen.getByLabelText('ANALYTICS.PUBLIC.ORDERS (this asset)')).toBeInTheDocument();
    expect(screen.queryByLabelText('Open asset ANALYTICS.PUBLIC.ORDERS')).not.toBeInTheDocument();
  });

  it('scrolls the graph inside its card rather than overflowing the page (mobile)', () => {
    renderGraph();
    const svg = screen.getByRole('img', { name: /Lineage graph/ });
    const scroller = svg.parentElement as HTMLElement;
    expect(scroller.style.overflowX).toBe('auto');
  });

  it('still draws the asset itself when it has no lineage', () => {
    render(
      <LineageGraph
        center={CENTER}
        upstream={[]}
        downstream={[]}
        edges={[]}
        onOpenAsset={vi.fn()}
      />,
    );
    // The asset's own box stays on screen — an <Empty> icon in its place read as
    // "there is nothing here", when the truth is "here is the asset, with nothing
    // attached to it yet". The words still say so.
    const graph = screen.getByRole('img', { name: /Lineage graph/ });
    expect(graph).toBeInTheDocument();
    expect(graph.querySelectorAll('path[marker-end]')).toHaveLength(0);
    expect(screen.getByLabelText(`${CENTER.name} (this asset)`)).toBeInTheDocument();
    expect(screen.getByText('No lineage recorded for this asset.')).toBeInTheDocument();
  });

  describe('warehouse-lineage advisories (#915, #916)', () => {
    function warehouse(over: Partial<WarehouseLineageStatus> = {}): WarehouseLineageStatus {
      return {
        connection_id: 'w1',
        name: 'Snowflake — Orders',
        type: 'snowflake',
        tier: 'snowflake_object_dependencies',
        degraded_reason: null,
        last_error: null,
        last_refreshed_at: null,
        ...over,
      };
    }

    function renderWith(warehouseStatus: WarehouseLineageStatus[]) {
      render(
        <LineageGraph
          center={CENTER}
          upstream={UP}
          downstream={DOWN}
          edges={EDGES}
          warehouseStatus={warehouseStatus}
          onOpenAsset={vi.fn()}
        />,
      );
    }

    // The defect: ONE info Alert covered both states, so "last refresh FAILED" —
    // an operational breakage — rendered at the same weight as "answers at a
    // coarser tier". Severity is carried by the antd alert class, so assert on it
    // rather than on wording, which can drift.
    it('renders a FAILED refresh as a warning, not an info note', () => {
      renderWith([warehouse({ last_error: 'The run failed to execute.' })]);
      const alert = screen.getByText(/Warehouse lineage refresh is failing/).closest('.ant-alert');
      expect(alert).toHaveClass('ant-alert-warning');
      expect(screen.getByText(/The run failed to execute\./)).toBeInTheDocument();
    });

    it('renders a degraded tier as an info note', () => {
      renderWith([warehouse({ degraded_reason: 'view-level only (Enterprise needed)' })]);
      const alert = screen.getByText(/Workspace lineage sources/).closest('.ant-alert');
      expect(alert).toHaveClass('ant-alert-info');
    });

    // The whole point of the split: when both exist, a failing source must be
    // visually distinct from a degraded one rather than merged into one box.
    it('separates a failing source from a degraded one when both are present', () => {
      renderWith([
        warehouse({ connection_id: 'w1', name: 'Failing SF', last_error: 'auth expired' }),
        warehouse({ connection_id: 'w2', name: 'Coarse SF', degraded_reason: 'view-level only' }),
      ]);
      const failing = screen.getByText(/refresh is failing/).closest('.ant-alert');
      const degraded = screen.getByText(/Workspace lineage sources/).closest('.ant-alert');
      expect(failing).toHaveClass('ant-alert-warning');
      expect(degraded).toHaveClass('ant-alert-info');
      expect(failing).not.toBe(degraded);
      // Each source appears under its own advisory, not both under one.
      expect(failing).toHaveTextContent('Failing SF');
      expect(failing).not.toHaveTextContent('Coarse SF');
      expect(degraded).toHaveTextContent('Coarse SF');
      expect(degraded).not.toHaveTextContent('Failing SF');
    });

    // #916: the advisory is workspace-wide by design (a tier is a property of the
    // SOURCE, not the asset), so a pure-UC asset legitimately lists Snowflake
    // connections. The framing has to say so or it reads as a bug.
    it('frames the degraded advisory as workspace-level, not asset-scoped', () => {
      renderWith([warehouse({ degraded_reason: 'view-level only' })]);
      expect(screen.getByText(/Workspace lineage sources/)).toBeInTheDocument();
      expect(
        screen.getByText(/workspace-wide source qualifiers, not findings about this asset/),
      ).toBeInTheDocument();
    });

    it('shows neither advisory when every source is healthy', () => {
      renderWith([warehouse()]);
      expect(screen.queryByText(/refresh is failing/)).not.toBeInTheDocument();
      expect(screen.queryByText(/Workspace lineage sources/)).not.toBeInTheDocument();
    });
  });
});

